mapper.select:
SELECT user_info.* FROM ( SELECT DISTINCT su.id, su.realname, su.avatar, su.sex, su.birthday, su.telephone, su.email, su.phone, su.main_dep_post_id, su.iz_hide_contact, su.sort, su.create_time FROM sys_user su join sys_user_depart sud on su.id = sud.user_id join sys_depart sd on sud.dep_id = sd.id where su.status = 1 and su.del_flag = 0 and su.username != '_reserve_user_external'
and sd.del_flag = 0 and sd.org_code LIKE #{bindOrgCode}
and su.realname like #{bindRealname}
) user_info order by user_info.sort,user_info.create_time desc
